def common():
 need(os.getuid()==os.geteuid()==0,'root_required');private_dir(OUT)
 need(Path('/proc/sys/kernel/random/boot_id').read_text().strip()==BOUND['boot'],'wrong_boot')
 need(proc_bytes('/proc/self/attr/current',256).rstrip(b'\0\n').decode()==EXPECTED_SELF,'wrong_operator_domain')
 anchors()
def preflight():
 common()
 for role,identity in GROUPS.items():
  p=proc(identity[0]);need(p is not None and p['identity']==list(identity) and p['state'] not in ('Z','X','x'),'original_role_identity:'+role)
 need(hasattr(os,'pidfd_open') and hasattr(signal,'pidfd_send_signal'),'pidfd_support_required_before_disable')
 fd=os.pidfd_open(GROUPS['supervisor'][0],0)
 try:need(proc(GROUPS['supervisor'][0])['identity']==list(GROUPS['supervisor']),'supervisor_changed_during_pidfd_probe')
 finally:os.close(fd)
 original_global_gate('preflight')
 originals=business_originals();runs=check_all_runs_terminal();saved=retained_state();slot=live_slot()
 for role,identity in GROUPS.items():
  p=proc(identity[0]);need(p is not None and p['identity']==list(identity) and p['state'] not in ('Z','X','x'),'role_changed_before_stop:'+role)
 value={'schema':'hepta.r9-r2-retirement-preflight.v1','state':'READY_FOR_DISABLE_AND_ONE_SUPERVISOR_TERM',
        'boot_id':BOUND['boot'],'observed_monotonic_ns':time.monotonic_ns(),'groups':{k:list(v) for k,v in GROUPS.items()},
        'original_business':originals,'all_original_run_terminals':runs,'preserved_state':saved,'live_slot':slot,
        'pidfd_probe_success':True,'signals_sent':0,'ui_actions':0,'new_model_requests':0,'automatic_replay':False}
 print(json.dumps(write('PREFLIGHT.json',value),sort_keys=True))
def retire():
 common()
 before=strict(stable(OUT/'PREFLIGHT.json',8*1024*1024)[0])
 need(before['state']=='READY_FOR_DISABLE_AND_ONE_SUPERVISOR_TERM' and before['groups']=={k:list(v) for k,v in GROUPS.items()},'preflight_binding')
 need(0<=time.monotonic_ns()-before['observed_monotonic_ns']<=30_000_000_000,'stale_stop_preflight')
 supervisor=GROUPS['supervisor'];observed=proc(supervisor[0]);term={'attempts':0,'target_identity':list(supervisor),'signal':'SIGTERM','via':'pidfd','old_module_disable_created_by_outer_operator':True}
 if observed is not None and observed['state'] not in ('Z','X','x'):
  need(observed['identity']==list(supervisor),'supervisor_pid_reused')
  try:fd=os.pidfd_open(supervisor[0],0)
  except OSError as e:
   if e.errno!=errno.ESRCH:raise
   term['result']='ORIGINAL_ALREADY_GONE_AFTER_DISABLE'
  else:
   try:
    current=proc(supervisor[0])
    if current is None or current['state'] in ('Z','X','x'):
     term['result']='ORIGINAL_ALREADY_EXITING_AFTER_DISABLE'
    else:
     need(current['identity']==list(supervisor),'supervisor_identity_changed_after_pidfd')
     write('TERM-INTENT.json',{'target_identity':list(supervisor),'pidfd_pins_original_process':True,'maximum_signal_attempts':1,'automatic_retry':False})
     term['attempts']=1
     try:signal.pidfd_send_signal(fd,signal.SIGTERM,None,0);term['result']='SIGTERM_SYSCALL_RETURNED'
     except OSError as e:
      if e.errno!=errno.ESRCH:raise
      term['result']='ESRCH_AFTER_ONE_SIGNAL_ATTEMPT'
   finally:os.close(fd)
 else:term['result']='ORIGINAL_ALREADY_EXITING_OR_ABSENT_AFTER_DISABLE'
 write('TERM-RESULT.json',term)
 deadline=time.monotonic()+60;quiet=[];last=None;groups=[x[0] for x in GROUPS.values()]
 while time.monotonic()<deadline:
  current=census(groups);last=current
  if not current['members']:
   current['kernel_group_absence']=kernel_absence(groups);quiet.append(current)
   if len(quiet)==2:break
  else:quiet=[]
  time.sleep(.25)
 need(len(quiet)==2,'original_groups_not_proven_absent_within_bound')
 original_global_gate('after')
 after=retained_state();need(after==before['preserved_state'],'claims_ledger_or_original_journal_changed_during_retirement')
 need(check_all_runs_terminal()==before['all_original_run_terminals'],'run_terminals_changed_during_retirement')
 need(business_originals()==before['original_business'],'original_business_changed_during_retirement')
 lock=os.open(DATA/'server.lock',os.O_RDONLY|os.O_NOFOLLOW)
 try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 finally:os.close(lock)
 result={'schema':'hepta.r9-r2-retirement-observation.v1','state':'ORIGINAL_FOUR_GROUPS_ABSENT_STATE_PRESERVED',
         'boot_id':BOUND['boot'],'original_role_identities':{k:list(v) for k,v in GROUPS.items()},'signal':term,'two_independent_censuses':quiet,'preserved_state':after,
         'server_lock_now_unheld':True,'original_task_terminals':[{'case_key':c['case_key'],'native_status':c['native_status'],'provider_terminal_kind':c['provider_terminal_kind']} for c in BOUND['cases']],'original_effect_count':len(BOUND['expected_action_ids']),'global_pending_clear':True,
         'old_claims_deleted':False,'old_task_terminal_rewritten':False,'model_requests':0,'ui_actions':0,
         'operator_waitpid_join_claim':False,'scope':'Process retirement observations only; supervisor owns child lifecycle. Original claim stop/exit files must be captured separately.',
         'automatic_restart':False,'automatic_replay':False}
 print(json.dumps(write('RETIREMENT.json',result),sort_keys=True))
def main():
 need(len(sys.argv)==2 and sys.argv[1] in ('preflight','retire'),'phase_required')
 def deadline(_s,_f):raise TimeoutError('bounded_retirement_probe_deadline')
 signal.signal(signal.SIGALRM,deadline);signal.alarm(70)
 try:(preflight if sys.argv[1]=='preflight' else retire)()
 except BaseException as e:
  with contextlib.suppress(Exception):write('ERROR-'+sys.argv[1]+'.json',{'state':'UNCONFIRMED_NO_RETRY','error_type':type(e).__name__,'error':str(e),'automatic_retry':False})
  raise
 finally:signal.alarm(0)
if __name__=='__main__':main()
